<?php require_once __DIR__ . '/_common.php'; $id=(int)($_GET['id']??$_POST['id']??0); if($id<=0) {header('Location: products.php');exit;} $s=$conn->prepare("SELECT * FROM products WHERE id=? AND vendor_id=?");$s->bind_param('ii',$id,$vendor_id);$s->execute();$r=$s->get_result();$product=$r->fetch_assoc();if(!$product){header('Location: products.php');exit;}$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){ $name=trim($_POST['name']??'');$description=trim($_POST['description']??'');$price=(float)($_POST['price']??0);$stock=(int)($_POST['stock']??0);$category=trim($_POST['category']??'');$status=$_POST['status']??'active';$new=vendor_image_upload($_FILES['image']??null,$error);if(!$name||$price<0||$stock<0){$error='Please enter valid product details.';}elseif(!$error){if($new){$u=$conn->prepare("UPDATE products SET name=?,description=?,price=?,stock=?,image=?,category=?,status=? WHERE id=? AND vendor_id=?");$u->bind_param('ssdisssii',$name,$description,$price,$stock,$new,$category,$status,$id,$vendor_id);}else{$u=$conn->prepare("UPDATE products SET name=?,description=?,price=?,stock=?,category=?,status=? WHERE id=? AND vendor_id=?");$u->bind_param('ssdissii',$name,$description,$price,$stock,$category,$status,$id,$vendor_id);}if($u->execute()){if($new&&!empty($product['image'])&&is_file(__DIR__.'/../assets/uploads/'.$product['image']))@unlink(__DIR__.'/../assets/uploads/'.$product['image']);header('Location: products.php');exit;}$error='Could not update product: '.$u->error;$product=array_merge($product,['name'=>$name,'description'=>$description,'price'=>$price,'stock'=>$stock,'category'=>$category,'status'=>$status]);}}
?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Edit Product - Bazario</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.0/dist/css/bootstrap.min.css" rel="stylesheet"><link href="style.css" rel="stylesheet"><link href="../assets/css/theme.css" rel="stylesheet"></head><body><div class="container py-5"><div class="glass-card p-4 mx-auto" style="max-width:850px"><div class="d-flex justify-content-between mb-4"><div><h2 class="text-white">Edit Product</h2><p class="text-white-50">Update details or replace the product image.</p></div><a href="products.php" class="btn btn-light-soft">Back</a></div><?php if($error):?><div class="alert alert-danger"><?=htmlspecialchars($error)?></div><?php endif;?><form method="post" enctype="multipart/form-data"><input type="hidden" name="id" value="<?=$id?>"><div class="row g-3"><div class="col-md-8"><label class="form-label">Product name</label><input name="name" class="form-control" value="<?=htmlspecialchars($product['name'])?>" required></div><div class="col-md-4"><label class="form-label">Category</label><input name="category" class="form-control" value="<?=htmlspecialchars($product['category']??'')?>"></div><div class="col-12"><label class="form-label">Description</label><textarea name="description" rows="5" class="form-control"><?=htmlspecialchars($product['description']??'')?></textarea></div><div class="col-md-4"><label class="form-label">Price (₹)</label><input name="price" type="number" min="0" step="0.01" class="form-control" value="<?=htmlspecialchars($product['price'])?>" required></div><div class="col-md-4"><label class="form-label">Stock</label><input name="stock" type="number" min="0" class="form-control" value="<?=htmlspecialchars($product['stock'])?>" required></div><div class="col-md-4"><label class="form-label">Status</label><select name="status" class="form-select"><option value="active" <?=$product['status']==='active'?'selected':''?>>Active</option><option value="inactive" <?=$product['status']==='inactive'?'selected':''?>>Inactive</option></select></div><div class="col-md-6"><label class="form-label">Current image</label><?php if(!empty($product['image'])&&is_file(__DIR__.'/../assets/uploads/'.$product['image'])):?><img src="../assets/uploads/<?=htmlspecialchars($product['image'])?>" class="img-fluid rounded" style="max-height:220px;object-fit:cover"><?php else:?><div class="placeholder rounded"><i class="fas fa-image"></i></div><?php endif;?></div><div class="col-md-6"><label class="form-label">Replace image</label><input name="image" type="file" accept="image/*" class="form-control"><div class="text-white-50 small mt-2">Leave empty to keep the current image.</div></div><div class="col-12"><button class="btn btn-brand btn-lg"><i class="fas fa-save me-2"></i>Save Changes</button></div></div></form></div></div></body></html>
